(()=>{'use strict';
const labels={draft:'Entwurf',review:'In Prüfung',approved:'Freigegeben'};let panel,callback,returnFocus;
function createPanel(){if(panel)return;panel=document.createElement('section');panel.className='preflight-panel';panel.hidden=true;panel.innerHTML='<div class="preflight-card" role="dialog" aria-modal="true" aria-labelledby="checkTitle"><h2 id="checkTitle">Prüfung vor dem Export</h2><div id="checkItems"></div><div class="ws-actions"><button id="checkContinue">Exportieren</button><button class="secondary" id="checkClose">Zurück zum Formular</button></div><p>Inhaltliche Prüfung von Tätigkeiten und Bewertungen bleibt erforderlich.</p></div>';document.body.append(panel);panel.querySelector('#checkClose').onclick=()=>{panel.hidden=true;callback=null;returnFocus?.focus();};panel.querySelector('#checkContinue').onclick=()=>{const action=callback;panel.hidden=true;callback=null;action?.();};panel.addEventListener('keydown',e=>{if(e.key==='Escape')panel.querySelector('#checkClose').click();if(e.key==='Tab'){const bs=[...panel.querySelectorAll('button')].filter(b=>!b.hidden);if(e.shiftKey&&document.activeElement===bs[0]){e.preventDefault();bs.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===bs.at(-1)){e.preventDefault();bs[0].focus();}}});}
function check(){return window.NexusModule?.check?.()||[];}
function show(action){createPanel();returnFocus=document.activeElement;callback=action;const issues=check(),container=panel.querySelector('#checkItems');container.replaceChildren();const ul=document.createElement('ul');for(const issue of issues){const li=document.createElement('li');li.className=issue.level;li.textContent=(issue.level==='error'?'Fehlt / widersprüchlich: ':'Hinweis: ')+issue.text;ul.append(li);}if(!issues.length){const p=document.createElement('p');p.textContent='Keine fehlenden Pflichtangaben, Platzhalter oder offensichtlichen Widersprüche gefunden.';container.append(p);}else container.append(ul);const next=panel.querySelector('#checkContinue');next.hidden=!action||issues.some(i=>i.level==='error');next.textContent=issues.length?'Trotz Hinweisen exportieren':'Exportieren';panel.hidden=false;panel.querySelector(next.hidden?'#checkClose':'#checkContinue').focus();return issues;}
window.NexusPreflight={run:action=>show(action),check,show:()=>show(null)};
document.addEventListener('DOMContentLoaded',()=>{
 const api=window.NexusModule;if(!api)return;
 const base=new URL('./',document.querySelector('script[src*="workflow.js"]').src);const store=window.NexusStore;
 let current=null,lastData='',initial='',dirty=false,lastUiApproved=false,approvalData='';
 const bar=document.createElement('section');bar.className='workflowbar';bar.dataset.workspaceControls='true';bar.innerHTML='<h2>Vorgang und Bearbeitungsstand</h2><div class="workflow-fields"><label>Titel des Entwurfs<input id="draftTitle" placeholder="z. B. Zeugnisentwurf November"></label><label>Status<select id="draftStatus"><option value="draft">Entwurf</option><option value="review">In Prüfung</option><option value="approved">Freigegeben</option></select></label><label>Prüfende / freigebende Person<input id="draftReviewer" placeholder="Bei Freigabe erforderlich"></label></div><div class="ws-actions"><button class="primary" id="draftSave">Entwurf speichern</button><button id="draftCopy">Als Kopie speichern</button><button id="draftCheck">Vorgang prüfen</button><a id="draftList">Alle Entwürfe</a></div><p id="draftMessage" role="status"></p><p>Lokal auf diesem Gerät. Kein automatisches Speichern oder Abgleich mit anderen Geräten. Der Freigabestatus dokumentiert den internen Bearbeitungsstand.</p>';
 const after=document.querySelector('.appnav');if(after)after.after(bar);else document.body.prepend(bar);
 const $=id=>bar.querySelector('#'+id);$('draftList').href=new URL('entwuerfe.html',base);$('draftList').style.cssText='padding:10px;display:inline-flex;align-items:center;color:#225378';
 const fingerprint=()=>JSON.stringify(api.getData());const msg=(s)=>$('draftMessage').textContent=s;
 function refresh(){try{const changed=fingerprint()!==lastData;const metaChanged=!!current&&($('draftTitle').value.trim()!==current.title||$('draftStatus').value!==current.status||$('draftReviewer').value.trim()!==(current.reviewer||''));dirty=changed||metaChanged;if(changed&&lastUiApproved&&fingerprint()!==approvalData){$('draftStatus').value='draft';lastUiApproved=false;msg('Inhalt geändert: Freigabestatus auf Entwurf zurückgesetzt. Bitte erneut prüfen und speichern.');}else if(dirty)msg('Ungespeicherte Änderungen.');$('draftMessage').className=dirty?'dirty-note':'';}catch(err){msg(err.message);}}
 function metadata(copy=false){let state=$('draftStatus').value;const reviewer=$('draftReviewer').value.trim();if(state==='approved'&&!copy){const issues=check();if(issues.some(x=>x.level==='error')){show(null);throw Error('Vor der Freigabe bitte die Pflichtangaben und Widersprüche korrigieren.');}if(!reviewer){$('draftReviewer').focus();throw Error('Für eine Freigabe bitte die freigebende Person eintragen.');}}const newApproval=state==='approved'&&(!current||current.status!=='approved'||fingerprint()!==lastData||reviewer!==(current.reviewer||''));return {id:copy?undefined:current?.id,type:api.type,title:($('draftTitle').value.trim()||api.title+(api.titleFromData?.()?' · '+api.titleFromData():''))+(copy?' – Kopie':''),status:copy?'draft':state,reviewer:copy?'':reviewer,reviewedAt:copy||state!=='approved'?'':newApproval?new Date().toISOString():current?.reviewedAt||'',data:api.getData()};}
 function save(copy){try{const next=store.save(metadata(copy));current=next;$('draftTitle').value=next.title;$('draftStatus').value=next.status;$('draftReviewer').value=next.reviewer||'';lastData=fingerprint();dirty=false;lastUiApproved=next.status==='approved';approvalData=lastUiApproved?lastData:'';const url=new URL(location.href);url.searchParams.set('draft',next.id);history.replaceState(null,'',url);msg('Gespeichert · '+new Date(next.updatedAt).toLocaleString('de-DE')+(next.reviewedAt?' · Freigabe dokumentiert am '+new Date(next.reviewedAt).toLocaleString('de-DE'):''));}catch(err){msg(err.message);}}
 $('draftSave').onclick=()=>save(false);$('draftCopy').onclick=()=>save(true);$('draftCheck').onclick=()=>show(null);
 const key=new URL(location.href).searchParams.get('draft');try{if(key){const loaded=store.get(key);if(!loaded||loaded.type!==api.type)throw Error('Dieser Entwurf ist hier nicht verfügbar.');api.setData(loaded.data);current=loaded;$('draftTitle').value=loaded.title;$('draftStatus').value=loaded.status;$('draftReviewer').value=loaded.reviewer||'';lastUiApproved=loaded.status==='approved';msg('Entwurf geladen · '+new Date(loaded.updatedAt).toLocaleString('de-DE'));}lastData=initial=fingerprint();approvalData=lastUiApproved?lastData:'';}catch(err){lastData=initial=fingerprint();msg(err.message);}
 let timer;const schedule=e=>{if(e.target.closest?.('.workflowbar,.preflight-panel,.output-panel'))return;clearTimeout(timer);timer=setTimeout(refresh,40);};document.addEventListener('input',schedule);document.addEventListener('change',schedule);document.addEventListener('click',schedule);document.addEventListener('pointerup',schedule);document.addEventListener('nexus:content-changed',schedule);
 bar.addEventListener('input',e=>{if(e.target.id==='draftStatus')return;refresh();});$('draftStatus').onchange=()=>{lastUiApproved=$('draftStatus').value==='approved';approvalData=lastUiApproved?fingerprint():'';dirty=true;msg('Bearbeitungsstand geändert. Bitte speichern.');};
 window.addEventListener('beforeunload',e=>{try{if(fingerprint()!==lastData||dirty){e.preventDefault();e.returnValue='';}}catch{}});
 window.NexusWorkflow={saved:()=>current,save:()=>save(false)};
});})();
